RTrigger1Open(CLK := bCylinder1Open OR g_bCylinder1Open);
RTrigger2Open(CLK := bCylinder2Open OR g_bCylinder2Open);
RTrigger3Open(CLK := bCylinder3Open OR g_bCylinder3Open);
RTrigger4Open(CLK := bCylinder4Open OR g_bCylinder4Open);
RTrigger5Open(CLK := bCylinder5Open OR g_bCylinder5Open);

RTrigger1Close(CLK := bCylinder1Close OR g_bCylinder1Close);
RTrigger2Close(CLK := bCylinder2Close OR g_bCylinder2Close);
RTrigger3Close(CLK := bCylinder3Close OR g_bCylinder3Close);
RTrigger4Close(CLK := bCylinder4Close OR g_bCylinder4Close);
RTrigger5Close(CLK := bCylinder5Close OR g_bCylinder5Close);

IF RTrigger1Open.Q THEN
  bCylinder1Open:= FALSE;(*资源回收*)
  g_bCylinder1Open := FALSE;
  IF NOT g_bClaw3CylForbid THEN
    g_boBlankingCyl01Up := TRUE;
    g_boBlankingCyl01Down := FALSE;
    g_bBlanking1DelayFlag := TRUE;
  END_IF;
  Ton_Cyl1Alarm(IN := FALSE);
  InPlaceDelay0(IN :=FALSE);
  g_bBlankingCyl1NoDownSignalAlarm := FALSE;
END_IF;
IF RTrigger1Close.Q THEN
  bCylinder1Close:= FALSE;(*资源回收*)
  g_bCylinder1Close := FALSE;
  g_boBlankingCyl01Up := FALSE;
  g_boBlankingCyl01Down := TRUE;
  g_bBlanking1DelayFlag := TRUE;
  Ton_Cyl1Alarm(IN := FALSE);
  bBlankingCyl1NoUpSignalAlarm := FALSE;
  InPlaceDelay0(IN :=FALSE);
END_IF;
(*hmi状态灯显示,自动下料机中也可使用*)
IF g_bBlankingUpInPlaceSignal0 AND g_boBlankingCyl01Up THEN(*使用到位信号*)
  InPlaceDelay0(IN :=FALSE);
  IF NOT bPreIsUpStateCyl1 THEN
    IF g_bBlankingCyl01UpInPlace AND g_bBlankingCyl02UpInPlace AND g_bBlankingCyl03UpInPlace AND g_bBlankingCyl04UpInPlace THEN
      bBlankingStateHmi1:= TRUE;
      g_bBlankingStateUp1 := TRUE;
      g_bBlankingStateDown1 := FALSE;
      bPreIsUpStateCyl1 := TRUE;
      Ton_Cyl1Alarm(IN := FALSE);
      bBlankingCyl1NoUpSignalAlarm := FALSE;
    ELSE
      Ton_Cyl1Alarm(IN := g_boBlankingCyl01Up,PT := LREAL_TO_TIME(FUN_MStoS(g_nBlankingUpInPlaceDelay0)));
      IF Ton_Cyl1Alarm.Q  THEN
        Ton_Cyl1Alarm(IN := FALSE);
        bBlankingCyl1NoUpSignalAlarm := TRUE;
      END_IF;
    END_IF; 
  ELSE
    IF g_CylAllStateUpDate.BoolArr[38] THEN
      bBlankingCyl1NoUpSignalAlarm := FALSE;
    ELSE
      bBlankingCyl1NoUpSignalAlarm := TRUE;
    END_IF;
  END_IF;
ELSIF g_bBlankingDownInPlaceSignal0 AND g_boBlankingCyl01Down THEN
  InPlaceDelay0(IN :=FALSE);
  IF bPreIsUpStateCyl1 THEN
    IF g_bBlankingCyl01DownInPlace AND g_bBlankingCyl02DownInPlace AND g_bBlankingCyl03DownInPlace AND g_bBlankingCyl04DownInPlace THEN
