      g_bBlankingStateUp1 := FALSE;
      g_bBlankingStateDown1 := TRUE;
      bPreIsUpStateCyl1 := FALSE;
      Ton_Cyl1Alarm(IN := FALSE);
      g_bBlankingCyl1NoDownSignalAlarm := FALSE;
    ELSE
      Ton_Cyl1Alarm(IN := g_boBlankingCyl01Down,PT := LREAL_TO_TIME(FUN_MStoS(g_nBlankingDownInPlaceDelay0)));
      IF Ton_Cyl1Alarm.Q  THEN
        Ton_Cyl1Alarm(IN := FALSE);
        g_bBlankingCyl1NoDownSignalAlarm := TRUE;
      END_IF;
    END_IF; 
  ELSE
    IF g_CylAllStateUpDate.BoolArr[39] THEN
      g_bBlankingCyl1NoDownSignalAlarm := FALSE;
    ELSE
      g_bBlankingCyl1NoDownSignalAlarm := TRUE;
    END_IF;
  END_IF;
ELSE(*使用延时信号*)
  bBlankingCyl1NoUpSignalAlarm := FALSE;
  g_bBlankingCyl1NoDownSignalAlarm := FALSE;
  IF g_bBlanking1DelayFlag THEN
    IF g_boBlankingCyl01Up THEN
      InPlaceDelay0(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_nBlankingUpInPlaceDelay0)));
    ELSE
      InPlaceDelay0(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_nBlankingDownInPlaceDelay0)));
    END_IF;
    IF InPlaceDelay0.Q THEN
       InPlaceDelay0(IN :=FALSE);
      IF g_boBlankingCyl01Up AND g_boBlankingCyl01Down=FALSE THEN
        bBlankingStateHmi1:= TRUE;
        g_bBlankingStateUp1 := TRUE;
        g_bBlankingStateDown1 := FALSE;
        g_bBlanking1DelayFlag := FALSE;
        bPreIsUpStateCyl1 := TRUE;
      END_IF;
      IF g_boBlankingCyl01Down AND g_boBlankingCyl01Up=FALSE THEN
        bBlankingStateHmi1:= FALSE;
        g_bBlankingStateUp1 := FALSE;
        g_bBlankingStateDown1 := TRUE;
        g_bBlanking1DelayFlag := FALSE;
        bPreIsUpStateCyl1 := FALSE;
      END_IF;
    END_IF;
  END_IF;
END_IF;

