IF ArrayConfigOutputNumber[36] AND NOT g_bBlankingUpInPlaceSignal0 THEN
  bBlankingStateHmi1:= TRUE;
  g_bBlankingStateUp1 := TRUE;
  g_bBlankingStateDown1 := FALSE;
  bPreIsUpStateCyl1 := TRUE;
  ArrayConfigOutputNumber[36] := FALSE;
END_IF;  
IF ArrayConfigOutputNumber[38] AND NOT g_bBlankingUpInPlaceSignal1 THEN
  bBlankingStateHmi2:= TRUE;
  g_bBlankingStateUp2 := TRUE;
  g_bBlankingStateDown2 := FALSE;
  bPreIsUpStateCyl2 := TRUE;
