  g_bBlankingStateDown5 := FALSE;
  bPreIsUpStateCyl5 := TRUE;
  ArrayConfigOutputNumber[44] := FALSE;
END_IF; 
(*打开输出口控制 气缸使用延时的状态切换  37-45 零件托举气缸下降的状态切换*)
IF ArrayConfigOutputNumber[37] AND NOT g_bBlankingDownInPlaceSignal0 THEN
  bBlankingStateHmi1:= FALSE;
  g_bBlankingStateUp1 := FALSE;
  g_bBlankingStateDown1 := TRUE;
  bPreIsUpStateCyl1 := FALSE;
  ArrayConfigOutputNumber[37] := FALSE;
END_IF;  
IF ArrayConfigOutputNumber[39] AND NOT g_bBlankingDownInPlaceSignal1 THEN
  bBlankingStateHmi2:= FALSE;
  g_bBlankingStateUp2 := FALSE;
  g_bBlankingStateDown2 := TRUE;
  bPreIsUpStateCyl2 := FALSE;
