END_IF;   
IF ArrayConfigOutputNumber[41] AND NOT g_bBlankingDownInPlaceSignal2 THEN
  bBlankingStateHmi3:= FALSE;
  g_bBlankingStateUp3 := FALSE;
  g_bBlankingStateDown3 := TRUE;
  bPreIsUpStateCyl3 := FALSE;
  ArrayConfigOutputNumber[41] := FALSE;
END_IF;   
IF ArrayConfigOutputNumber[43] AND NOT g_bBlankingDownInPlaceSignal3 THEN
